//! 🧾️ Optional dictionaries preserve presence independently of their sparse entry owners.
use crate::{LayoutDiff,LayoutDataEntriesDelta,DataFieldsPresence};
use semio_s_artifact_layout_layout_model::snapshot::LayoutSnapshot;
use semio_framework_value_dictionary::{QuestionDictionary,QuestionDictionaryEntry};
use semio_framework_os_kernel::ApplyCapability;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneRef,RetainedCloneClose,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep}};
use super::super::{collection::RetainedCollection,keyed_plan::PlanAdvance};
use std::mem::{size_of,ManuallyDrop};
fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<QuestionDictionary>>()*4+128,depth:1,..Default::default()}}
fn fault()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"Layout retained dictionary phase is invalid")}
fn source(d:RetainedCloneRef<'_,LayoutDiff>)->RetainedCloneRef<'_,LayoutDataEntriesDelta>{d.project(11,|d|d.data_fields.as_ref().unwrap()).project(1,|d|d.entries.as_ref().unwrap())}
pub struct DataWork{entries:RetainedCollection<QuestionDictionaryEntry,LayoutDataEntriesDelta>,old:ManuallyDrop<Option<QuestionDictionary>>,retirement:RetainedCloneClose,phase:u8,closing:bool}
impl Default for DataWork{fn default()->Self{Self{entries:RetainedCollection::new(),old:ManuallyDrop::new(None),retirement:Default::default(),phase:0,closing:false}}}
impl DataWork{
 fn active(d:&LayoutDiff)->bool{d.data_fields.as_ref().is_some_and(|d|d.presence!=Some(DataFieldsPresence::Deleted)&&d.entries.is_some())}
 fn baseline<'a>(d:&LayoutDiff,post:&'a LayoutSnapshot)->&'a [QuestionDictionaryEntry]{if d.data_fields.as_ref().is_some_and(|d|d.presence==Some(DataFieldsPresence::Replaced)){&[]}else{post.data_fields.as_ref().map_or(&[],|d|d.entries.as_slice())}}
 pub fn preflight_demand(&self,d:RetainedCloneRef<'_,LayoutDiff>,post:&LayoutSnapshot,body:usize)->Result<RetirementDemand,ValueError>{if Self::active(d.get()){self.entries.preflight_demand(source(d),Self::baseline(d.get(),post),body)}else{Ok(fixed())}}
 pub fn preflight(&mut self,d:RetainedCloneRef<'_,LayoutDiff>,post:&LayoutSnapshot,body:usize,g:RetainedCloneGrant)->Result<PlanAdvance,ValueError>{let demand=self.preflight_demand(d,post,body)?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,demand){return Ok(PlanAdvance{progress:Default::default(),done:false,error:None})}if let Some(delta)=&d.get().data_fields{if post.data_fields.is_none()&&delta.presence.is_none()&&delta.entries.as_ref().is_some_and(|e|!e.removed.is_empty()||!e.inserted.is_empty()||!e.moved.is_empty()){return Ok(PlanAdvance{progress:RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()},done:false,error:Some("layout.data.missing-target")})}}if Self::active(d.get()){self.entries.preflight(source(d),Self::baseline(d.get(),post),body,g)}else{Ok(PlanAdvance{progress:RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()},done:true,error:None})}}
 pub fn commit_demand(&self,d:&LayoutDiff)->Result<RetirementDemand,ValueError>{if self.phase==0||!Self::active(d){Ok(fixed())}else{self.entries.membership_commit_demand()}}
 pub fn commit(&mut self,d:&LayoutDiff,post:&mut LayoutSnapshot,g:RetainedCloneGrant,capability:ApplyCapability)->Result<RetainedCloneStep,ValueError>{let demand=self.commit_demand(d)?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,demand){return Ok(RetainedCloneStep::Progress(Default::default()))}let p=RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()};if self.phase==0{if let Some(delta)=&d.data_fields{match delta.presence{Some(DataFieldsPresence::Deleted)=>*self.old=post.data_fields.take(),Some(DataFieldsPresence::Replaced)=>{*self.old=post.data_fields.take();post.data_fields=Some(QuestionDictionary{entries:Vec::new()})},Some(DataFieldsPresence::Created)=>if post.data_fields.is_none(){post.data_fields=Some(QuestionDictionary{entries:Vec::new()})},None=>{}}}self.phase=1;return Ok(RetainedCloneStep::Progress(p))}if !Self::active(d)||post.data_fields.is_none(){return Ok(RetainedCloneStep::Complete(p))}self.entries.commit_membership(&mut post.data_fields.as_mut().unwrap().entries,g,capability)}
 pub fn begin_close(&mut self){self.closing=true;self.entries.begin_close()}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.entries.terminal_is_empty(){return self.entries.close_demand(body)}self.retirement.next_owner_demands::<QuestionDictionary>(self.old.is_some(),&None,body)}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(fault())}let d=self.close_demand(g.maximum_copy_bytes)?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.entries.terminal_is_empty(){return self.entries.close_step(g).map(|step|RetainedCloneStep::Progress(step.progress()))}if !self.retirement.is_empty(){return self.retirement.step_granted(g).map(|step|RetainedCloneStep::Progress(step.progress()))}if let Some(step)=self.retirement.begin_granted(&mut self.old,g)?{return Ok(step)}Ok(RetainedCloneStep::Complete(Default::default()))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.entries.terminal_is_empty()&&self.old.is_none()&&self.retirement.is_empty()}
}
impl Drop for DataWork{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"dictionary original owners require funded close")}}
